"""Render the research report from the frozen analysis; no network access."""
from pathlib import Path
import json, html, hashlib

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'dist/analysis'
D = json.loads((OUT/'data.json').read_text())
B = json.loads((ROOT/'research/analysis/literature/bibliography.json').read_text())
esc = lambda x: html.escape(str(x))
cov = D['coverage']
num = lambda x: '—' if x is None else f'{x:.1f}'
parts=[]
def section(title, text):
    parts.append(f'<section><h2>{esc(title)}</h2>{text}</section>')
def p(s): return '<p>'+s+'</p>'
def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def figure(fid):
    f=next((f for f in D['figures'] if f['id']==fid),None)
    if not f:return ''
    return '<figure><img loading="lazy" src="'+esc(f['path'].replace('analysis/','',1))+'" alt="'+esc(f['title'])+'"><figcaption><strong>'+esc(f['title'])+'.</strong> '+esc(f['caption'].replace('common channeling identity terms','predefined practitioner/entity names and genre terms').replace('Common identity words are masked.','Predefined names and genre terms are masked.'))+'</figcaption></figure>'

section('What this sample shows',p(f'The merged index contains <strong>{cov["videoCount"]} unique YouTube video IDs</strong>. Duration metadata is available for {cov["durationCount"]} and an exact publication day for {cov["dateCount"]}. The table groups uploads by publishing account; these groups must not be counted as distinct human mediums. The supplied draft adds substantial coverage, but its mostly capped listings do not measure complete channel histories.')+p('The clearest descriptive contrast is upload length: the sampled official Bashar account has a mean of 3.4 minutes, while the sampled Bashar Channeling Podcast account has a mean of 103.5 minutes. The examples suggest a role for excerpt and compilation formats, but no formal format annotation has been performed. A single overall average would conceal those differences. Each dashboard row therefore reports measured/indexed counts, mean, median and quartiles.')+p(f'Available captions make a substantive pilot possible: {D["transcripts"]["available"]} of {D["transcripts"]["attempted"]} selected uploads yielded text, with {cov["englishPilotCount"]} English documents included in the main analysis. Learned embeddings were actually computed with a pinned 384-dimensional MiniLM model. They measure text resemblance; they do not validate the claimed source of a communication.'))

section('How the uploaded draft changed the evidence',p('The Claude ZIP contains 466 video rows, including 457 unique valid video IDs and nine unlinked leads. Fourteen IDs overlap the earlier 482-video index, producing the 925-video union. Its 450 supplied duration values include one originally marked as an estimate; the initial primary duration analysis used 449. Fresh metadata now takes precedence where available, with inherited values and discrepancies preserved.')+p('The directory’s 92 rows are not 92 verified YouTube accounts: only 53 contain account routes. Some missing rows reflect collection-credit exhaustion. Relative date labels such as “one month ago” remain labels rather than invented publication dates. The ZIP contained summaries and research notes, not full transcripts. The supplied entity-frequency and audience charts were replaced with plots whose units and sample coverage are explicit.'))

chosen=[c for c in D['channels'] if c.get('url','').lower() in {'https://www.youtube.com/@basharchanneledbydarrylanka','https://www.youtube.com/@basharchannelingpodcast','https://www.youtube.com/@athinakrol','https://www.youtube.com/@thegalacticguide111','https://www.youtube.com/@tylerellison','https://www.youtube.com/@danielscranton','https://www.youtube.com/@lorieladd'}]
section('Average length belongs to an account and a sample',table(['Publishing account','Measured / indexed','Mean min','Median min','Middle 50% min'],[[f'<a href="{esc(c["url"])}">{esc(c["name"])}</a>',f'{c["durationCount"]} / {c["videoCount"]}',num(c['meanMinutes']),num(c['medianMinutes']),num(c['q1Minutes'])+'–'+num(c['q3Minutes'])] for c in chosen])+p('These examples are selected for continuity with the research brief, not as a ranking. The complete downloadable table includes every group and null values. A mean well above the median suggests that longer uploads influence the average; it is a reason to inspect formats, not a measure of quality or popularity.')+figure('duration')+figure('coverage')+figure('duration-format'))

section('Titles describe how uploads are presented',p('Nine predefined, overlapping keyword families provide an inspectable first pass through English-likely titles. A cell measures the fraction of eligible titles with at least one match. The denominator excludes short or non-English-likely titles under a documented language heuristic. Current watch-page titles replace supplied translations for analysis, while variants remain available for audit.')+p('Frequent words can reflect packaging, branding, repost titles or the eliciting question. They are not equivalent to the frequency of an idea in a session. Topic names are descriptive indicators and have not been validated by blinded human coders.')+figure('title-topics')+figure('lexical-similarity'))

section('Captions permit a closer comparison, with important boundaries',p('The caption pilot deliberately covers multiple accounts and is not random. Thirty documents from 17 publishing groups enter the main English analysis; 13 groups have at least two documents for account-level similarity. Most retrieved tracks are automatic. Speech recognition errors, hosts, questions, advertisements and promotional material remain in the text; no speaker diarization or audio verification was performed.')+p('Long captions are encoded in explicit 240-wordpiece chunks, pooled to videos and then equally to accounts. This avoids silently encoding only the beginning of a session or letting longer recordings contribute more chunks to an account representation. The short final chunk nevertheless receives equal weight, a choice tested in the manuscript extension below. Keyword rates are calculated per 1,000 alphabetic word tokens for each video and then averaged equally within account.')+figure('caption-topics')+figure('caption-similarity')+figure('title-caption-indicators')+figure('caption-within-between')+p('A separate Daniel Scranton check links one official written message to its exact YouTube upload. Ordered matches cover 96.7% of the written message but only 42.5% of caption word tokens under the supplementary concordance tokenizer. That Unicode word-token alignment differs from the main analysis’s alphabetic-token keyword-rate calculation. In a caption-observed closing-window check, roughly half the upload’s alphabetic words occur after the closing. This single example shows why an upload-level vector cannot automatically be interpreted as the vocabulary of a claimed entity. It does not establish caption accuracy across the corpus.'))

section('What survives a change in analysis choices',p('The pipeline compares raw and name-and-genre-masked titles, excludes repeated masked-title strings, repeatedly draws balanced five-title samples, and trims the first and last 10% of whitespace-separated caption tokens after masking. These are descriptive sensitivity analyses on the observed sample, not population confidence intervals. Exact repeated titles are only one proxy for reposts; different edits of the same original session can remain.')+p('In the independently checked 13-account caption comparison, full-versus-trimmed pair rankings correlate at 0.9695, while nearest neighbors change for four accounts. Broad pair ordering and individual neighbor labels therefore tell different stability stories. Trimming is not a substitute for separating speakers or promotional segments.')+table(['Sensitivity comparison','Account pairs','Spearman rank correlation'], [[esc(label),D['diagnostics'][key]['pairCount'],f"{D['diagnostics'][key]['spearmanRankCorrelation']:.3f}"] for label,key in [('Raw versus name-and-genre-masked titles','rawVsMaskedTitles'),('All versus repeated-title-excluded titles','deduplicatedVsAllTitles'),('Full versus trimmed captions','captionFullVsTrimmed'),('Matched title versus caption centroids','matchedTitleVsCaption')]])+p('The title/caption pilot has 25 eligible video IDs. The two-video-per-account rule leaves the same 22 contributing IDs on both sides, yielding 11 comparable account centroids and 55 account pairs. Their ranking correlation is 0.206, so headline-based similarity is a weak substitute for caption-based similarity in this selected pilot. Differences can then be described as text-layer differences within that pilot, rather than confused with different video samples. Even in a matched set, a long caption has more chances to contain a keyword than a title.'))

paper_path=ROOT/'research/paper/generated/paper-results.json'
if paper_path.exists():
    P=json.loads(paper_path.read_text())
    section('Manuscript extension: local sensitivity',p('The working paper adds two targeted checks to the frozen dashboard dataset. Omitting one account at a time changes the matched title/caption rank correlation from −0.043 to 0.379; each omission leaves ten accounts and 45 dependent pairs. This is an influence diagnostic, not a confidence interval.')+p('Reweighting the same caption chunks by content WordPiece count produces a rank correlation of 0.984 across 78 pairs, yet changes the nearest account for 2 of 13 accounts. Equal weighting across videos is retained. The 30-caption corpus yields 320 chunks; 26 captions from 13 accounts contribute to this comparison.')+'<figure><img src="paper/matched-similarity.png" alt="Matched title and caption cosine scores and account omission diagnostic"><figcaption>Matched text-layer comparison uses 22 videos, 11 accounts and 55 dependent pairs. Each omission removes one account and its incident pairs. The range is not a population uncertainty interval.</figcaption></figure><figure><img src="paper/sensitivity.png" alt="Four sensitivity rank correlations and caption word counts"><figcaption>Four distinct perturbations preserve different levels of pair ordering; captions range from 87 to 8,588 alphabetic words. Global rank stability does not establish a stable nearest account or validated thematic agreement.</figcaption></figure>'+p('<a href="channeling-atlas-paper.pdf">Read the working paper (PDF)</a> · <a href="channeling-atlas-overleaf.zip">Download the LaTeX / Overleaf source</a> · <a href="paper/paper-results.json">Numerical results</a> · <a href="paper/bibliography.csv">Expanded scholarly source register</a>. Human authorship, construct validation, institutional ethics determination and submission checklist answers remain TBD.'))

section('How this relates to published work',p('The closest 2026 studies by Wahbeh and Glick use prospectively elicited interviews with three channelers and standardized topics. Their embedding and qualitative analyses motivate matched prompts and contextual reading. Their reported similarities cannot be compared directly to unprompted YouTube uploads with different speakers, lengths and editing. The public supplement was inspected; missing participant inputs and analysis components prevent a replication claim.')+p('A 2023 exploratory study asked 15 channelers ten scientific and metaphysical questions. Its quantitative comparison covered seven US participants and reported very little cross-channeler correspondence; the qualitative analysis included all 15 participants and identified some shared themes. Different prompts and measures prevent a simple contradiction or pooled estimate. Together, these studies illustrate why thematic resemblance, answer agreement and claimed origin must remain separate questions.')+p('Sentence-BERT supplies the general embedding method. Topic-model evaluation and small-corpus studies motivate explicit units, human validation and stability checks. Recent embedding benchmarks and candidate models are included in the literature register; MiniLM is an executed baseline, not a state-of-the-art claim. BERTopic and larger multilingual encoders were reviewed as possible follow-ups but were not run in this release.'))

section('Analysis rounds and manuscript review',table(['Round','Build','Independent check and correction'],[
 ['1','Normalize the ZIP, merge unique video IDs, calculate durations and title indicators, build the dashboard.','Reconstruct numeric values and topic counts; distinguish capped samples, missing dates, accounts and people.'],
 ['2','Acquire fresh metadata and captions; compute pinned learned embeddings; retain title-language variants.','Reconstruct centroids and cosine matrices; correct date-field binding, source precedence, caption hashing and denominator descriptions.'],
 ['3','Freeze the completed metadata pass; add paired text-layer and sensitivity diagnostics; export reproducible features and revised figures.','Recheck provenance, numeric/vector outputs, figure labels, UI behavior and offline rebuilding before publication.'],
 ['4','After the dashboard was published, expand peer-reviewed sources and compile the full manuscript.','Audit arguments and denominators, inspect all PDF pages, and identify plot and wording corrections.'],
 ['5','Correct methods and figures, add token-weighted caption pooling and publishable source descriptions.','Independently verify 231 numeric checks and review all 12 pages; close substantive findings.'],
 ['6','Correct the final two wording/reference details and freeze the paper and Overleaf package.','Verify source and numerical invariance, offline regeneration, citations, all pages, package compilation and dashboard links.']
])+p('Six model agents provide differentiated source, corpus, methods, implementation, literature and interface reviews under a coordinating agent. This is an AI-assisted review process, not independent human peer review. All 18 available custom research/design skills were read; transferable evidence, provenance and review practices were applied, while unrelated physics, gaming and other domain-specific instructions were marked inapplicable. Exact inputs, hashes, reviews and corrections are retained in the research directory.'))

section('Limits and testable next questions',p('The discovery index is a convenience sample with English and platform-access biases. Historical uploads, active accounts, original mediums, guests, repost channels and claimed entities are different units. This analysis does not estimate the worldwide number of currently active ET channeling mediums. Metadata visibility does not imply that a recording is playable or freely available.')+table(['Question','Next evidence needed','Current status'],[
 ['Do upload formats explain more variation than claimed entity labels?','Human-reviewed format and speaker labels; sufficient matched accounts; account-level resampling.','TBD: exploratory hypothesis.'],
 ['Do topic similarities remain after hosts and promotion are removed?','Timestamped speaker/segment annotation with agreement checks.','TBD: one supplementary closing-window example only.'],
 ['Do claims about the same topic agree in substance?','Matched prompts or close-reading units, blinded coding and an agreement measure.','TBD: cosine similarity alone does not answer this.'],
 ['Are results stable across models and languages?','A multilingual benchmark subset with human similarity judgments and licensed text.','TBD: one English encoder executed.'],
 ['Can a defensible activity count be estimated?','A defined public sampling frame, deduplicated human identities and verified dated original uploads.','TBD: account and video counts are not medium counts.']
]))

refs=[]
expanded=ROOT/'research/paper/literature/source-register.json'
if expanded.exists():
    for x in json.loads(expanded.read_text()):
        refs.append('<li><a href="'+esc(x['primary_url'])+'">'+esc(x['title'])+'</a> ('+esc(x['year'])+'). '+esc(x['venue'])+'. '+esc(x['publication_class'])+'. <em>Access:</em> '+esc(x['access_depth'])+'</li>')
else:
    for x in B['papers']:
        refs.append('<li><a href="'+esc(x.get('url') or x.get('doi',''))+'">'+esc(x['title'])+'</a></li>')
section('Sources and reusable files',p('The annotated bibliography records publication status, access level and limitations. The release provides source-linked metadata, numeric features and code; full captions and model weights are not redistributed.')+'<ul><li><a href="channeling-atlas-paper.pdf">Working paper PDF</a></li><li><a href="channeling-atlas-overleaf.zip">LaTeX / Overleaf source ZIP</a></li><li><a href="channel-metrics.csv">Channel metrics CSV</a></li><li><a href="video-observations.csv">Video observations CSV</a></li><li><a href="channeling-analysis-bundle.zip">Analysis, code and review bundle</a></li><li><a href="bibliography.csv">Annotated bibliography CSV</a></li><li><a href="https://github.com/occult-kranti/channels-ET/tree/main">GitHub research directory</a></li></ul>'+'<ol class="references">'+''.join(refs)+'</ol>')

style='''body{margin:0;background:#f5f3ed;color:#192723;font:18px/1.65 Georgia,serif}main{max-width:1060px;margin:auto;padding:48px 28px 90px}a{color:#14685e}header{border-bottom:2px solid #234c44;padding-bottom:24px}h1{font-size:clamp(32px,5vw,53px);line-height:1.1;max-width:860px}h2{font:600 28px/1.25 system-ui;margin-top:52px}p{max-width:860px}nav,.meta{font:14px/1.6 system-ui}nav{display:flex;gap:24px;flex-wrap:wrap}table{border-collapse:collapse;width:100%;font:14px/1.5 system-ui;background:white}th,td{padding:12px;text-align:left;border-bottom:1px solid #d6ded9;vertical-align:top}th{background:#e3ebe5}figure{margin:30px 0;background:white;padding:14px;border:1px solid #d6ded9}img{width:100%;height:auto}figcaption{font:14px/1.55 system-ui;color:#40534b;padding:12px 4px}.scroll{overflow-x:auto}.references{font:14px/1.65 system-ui}.references li{margin-bottom:10px}footer{border-top:1px solid #9aad9f;margin-top:40px;font:13px/1.6 system-ui}@media(max-width:600px){main{padding:28px 16px}figure{padding:4px}table{min-width:620px}}@media print{body{background:white;font-size:11pt}nav{display:none}main{padding:0}figure,table{break-inside:avoid}h2{break-after:avoid}a{color:inherit}}'''
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Channeling Atlas — research report</title><style>'+style+'</style><main><header><nav><a href="../#/analysis">← Interactive analysis</a><a href="channeling-analysis-bundle.zip">Download research bundle</a></nav><p class="meta">CHANNELING ATLAS · RESEARCH SNAPSHOT · 23 OCTOBER 2026</p><h1>Upload formats and text layers shape the comparisons</h1><p>A source-linked exploratory analysis of the supplied Claude research and the existing YouTube index.</p></header>'+''.join(parts)+'<footer>Analysis data SHA-256: '+hashlib.sha256((OUT/'data.json').read_bytes()).hexdigest()+'<br>Generated from frozen evidence by research/analysis/build_report.py.</footer></main></html>'
(OUT/'report.html').write_text(page)
(OUT/'bibliography.csv').write_bytes((ROOT/'research/analysis/literature/bibliography.csv').read_bytes())
print('Report written:',OUT/'report.html')
